      ctx.fillStyle = '#a5f3ff';
      ctx.beginPath(); ctx.arc(g.x, g.y, r * 2.1, 0, TAU); ctx.fill();
      ctx.globalAlpha = 1;
      ctx.fillStyle = g.v > 20 ? '#ffe066' : g.v > 5 ? '#7cf6ff' : '#c9f7ff';
      ctx.beginPath();
      ctx.moveTo(g.x, g.y - r);
      ctx.lineTo(g.x + r * 0.8, g.y);
      ctx.lineTo(g.x, g.y + r);
      ctx.lineTo(g.x - r * 0.8, g.y);
      ctx.closePath();
      ctx.fill();
    }
    ctx.restore();
  }

  function drawChests() {
    for (const c of Game.chestDrops) {
      const s = 1 + Math.sin(c.pulse * 5) * 0.09;
      const fade = c.life < 4 ? 0.4 + 0.6 * Math.abs(Math.sin(c.life * 6)) : 1;
      ctx.save();
      ctx.globalAlpha = fade;
      ctx.translate(c.x, c.y);
      ctx.scale(s, s);
      ctx.shadowColor = '#ffe066';
      ctx.shadowBlur = 18;
      ctx.fillStyle = '#c98a2b';
      roundRect(-13, -9, 26, 18, 4); ctx.fill();
      ctx.fillStyle = '#ffe066';
      roundRect(-13, -9, 26, 7, 3); ctx.fill();
      ctx.fillStyle = '#fff4c2';
      ctx.fillRect(-2.5, -5, 5, 10);
      ctx.restore();
    }
  }

  /* ------------------------------------------------------------------ */
  function enemyShape(e) {
    const r = e.r;
    const col = e.hitFlash > 0 ? '#ffffff' : e.color;
    ctx.save();
    ctx.translate(e.x, e.y);

    // glow
    ctx.globalAlpha = 0.25;
    ctx.fillStyle = col;
    ctx.beginPath(); ctx.arc(0, 0, r * 1.7, 0, TAU); ctx.fill();
    ctx.globalAlpha = 1;

    const wob = Math.sin(time * 6 + e.x * 0.05) * 0.06;

    switch (e.def.shape) {
      case 'dart': {
        const a = Math.atan2(Game.player.y - e.y, Game.player.x - e.x);
        ctx.rotate(a);
        ctx.fillStyle = col;
        ctx.beginPath();
        ctx.moveTo(r * 1.5, 0); ctx.lineTo(-r, r * 0.85); ctx.lineTo(-r * 0.4, 0); ctx.lineTo(-r, -r * 0.85);
        ctx.closePath(); ctx.fill();
        break;
      }
      case 'spitter': {
        ctx.fillStyle = col;
        ctx.beginPath();
        for (let i = 0; i < 7; i++) {
          const a = (TAU * i) / 7;
          const rr = i % 2 === 0 ? r : r * 0.62;
          ctx[i ? 'lineTo' : 'moveTo'](Math.cos(a) * rr, Math.sin(a) * rr);
        }
        ctx.closePath(); ctx.fill();
        ctx.fillStyle = '#1b0b2e';
        ctx.beginPath(); ctx.arc(0, 0, r * 0.34, 0, TAU); ctx.fill();
        break;
      }
      case 'brute': {
        ctx.rotate(wob * 2);
        ctx.fillStyle = col;
        roundRect(-r, -r * 0.9, r * 2, r * 1.8, r * 0.5); ctx.fill();
        ctx.fillStyle = 'rgba(0,0,0,0.28)';
        roundRect(-r * 0.6, -r * 0.5, r * 1.2, r * 0.35, r * 0.15); ctx.fill();
        ctx.fillStyle = '#fff';
        ctx.beginPath(); ctx.arc(-r * 0.32, -r * 0.25, r * 0.16, 0, TAU); ctx.fill();
        ctx.beginPath(); ctx.arc(r * 0.32, -r * 0.25, r * 0.16, 0, TAU); ctx.fill();
        break;
      }
      case 'ghost': {
        ctx.globalAlpha = 0.65 + Math.sin(time * 3 + e.y * 0.01) * 0.2;
        ctx.fillStyle = col;
        ctx.beginPath(); ctx.arc(0, 0, r, 0, TAU); ctx.fill();
        ctx.globalAlpha = 1;
        ctx.strokeStyle = 'rgba(255,255,255,0.5)';
        ctx.lineWidth = 1.5;
        ctx.beginPath(); ctx.arc(0, 0, r * 0.62, 0, TAU); ctx.stroke();
        break;
      }
      case 'elite':
      case 'boss': {
        const spikes = e.def.isBoss ? 12 : 8;
        ctx.rotate(time * 0.6);
        ctx.fillStyle = col;
        ctx.beginPath();
        for (let i = 0; i < spikes * 2; i++) {
          const a = (TAU * i) / (spikes * 2);
          const rr = i % 2 === 0 ? r * 1.28 : r * 0.78;
          ctx[i ? 'lineTo' : 'moveTo'](Math.cos(a) * rr, Math.sin(a) * rr);
        }
        ctx.closePath(); ctx.fill();
        ctx.rotate(-time * 1.4);
        ctx.fillStyle = 'rgba(0,0,0,0.4)';
        ctx.beginPath(); ctx.arc(0, 0, r * 0.55, 0, TAU); ctx.fill();
        ctx.fillStyle = '#fff';
        ctx.beginPath(); ctx.arc(0, 0, r * 0.26, 0, TAU); ctx.fill();
        ctx.fillStyle = '#ff1f4b';
        ctx.beginPath(); ctx.arc(0, 0, r * 0.13, 0, TAU); ctx.fill();
        break;
      }
      default: { // blob
        ctx.scale(1 + wob, 1 - wob);
        ctx.fillStyle = col;
        ctx.beginPath(); ctx.arc(0, 0, r, 0, TAU); ctx.fill();
        ctx.fillStyle = 'rgba(255,255,255,0.75)';
        ctx.beginPath(); ctx.arc(-r * 0.28, -r * 0.3, r * 0.22, 0, TAU); ctx.fill();
        ctx.beginPath(); ctx.arc(r * 0.3, -r * 0.22, r * 0.15, 0, TAU); ctx.fill();
      }
    }
    ctx.restore();
  }

  function drawEnemies() {
    for (const e of Game.enemies) {
      if (e.dead) continue;
      // cull offscreen (with margin) for perf
      if (e.x < Game.view.camX - 80 || e.x > Game.view.camX + W + 80 ||
          e.y < Game.view.camY - 80 || e.y > Game.view.camY + H + 80) continue;

      enemyShape(e);

      // hp bar for chunky enemies
      if ((e.def.isBoss || e.def.isElite || e.def.hp >= 60) && e.hp < e.maxHp) {
        const w = e.r * 2.2, h = e.def.isBoss ? 7 : 4;
        const x = e.x - w / 2, y = e.y - e.r - (e.def.isBoss ? 20 : 12);
        ctx.fillStyle = 'rgba(0,0,0,0.55)';
        roundRect(x - 1, y - 1, w + 2, h + 2, 2); ctx.fill();
        ctx.fillStyle = e.def.isBoss ? '#ff3d6e' : '#ff8fab';
        roundRect(x, y, w * Math.max(0, e.hp / e.maxHp), h, 2); ctx.fill();
      }
    }
  }

  /* ------------------------------------------------------------------ */
  function drawPlayer() {
    const p = Game.player;
    const col = Game.character.color;

    // trail
    ctx.save();
    for (let i = 0; i < p.trail.length; i++) {
      const t = p.trail[i];
      const k = t.life / 0.4;
      if (k <= 0) continue;
      ctx.globalAlpha = k * 0.22;
      ctx.fillStyle = col;
      ctx.beginPath(); ctx.arc(t.x, t.y, p.r * k * 0.9, 0, TAU); ctx.fill();
    }
    ctx.restore();

    ctx.save();
    ctx.translate(p.x, p.y);

    // aura
    const ag = ctx.createRadialGradient(0, 0, 2, 0, 0, p.r * 3.2);
    ag.addColorStop(0, 'rgba(124,246,255,0.42)');
    ag.addColorStop(1, 'rgba(124,246,255,0)');
    ctx.fillStyle = ag;
    ctx.beginPath(); ctx.arc(0, 0, p.r * 3.2, 0, TAU); ctx.fill();

    if (p.iFrame > 0 && Math.floor(p.iFrame * 18) % 2 === 0) ctx.globalAlpha = 0.45;

    // tentacles
    ctx.strokeStyle = col;
    ctx.lineWidth = 3;
    ctx.lineCap = 'round';
    const speed = Math.hypot(p.vx, p.vy);
    for (let i = 0; i < 5; i++) {
      const base = Math.PI * 0.5 + (i - 2) * 0.32 + (p.facing > 0 ? 0 : Math.PI * 0.15);
      const a = base + Math.atan2(-p.vy, -p.vx || 0.001) * 0.12;
      const sway = Math.sin(time * 7 + i) * 0.28 * (0.4 + speed / 300);
      ctx.beginPath();
      ctx.moveTo(Math.cos(a) * p.r * 0.5, Math.sin(a) * p.r * 0.5);
      ctx.quadraticCurveTo(
        Math.cos(a + sway) * p.r * 1.7, Math.sin(a + sway) * p.r * 1.7,
        Math.cos(a + sway * 1.6) * p.r * 2.5, Math.sin(a + sway * 1.6) * p.r * 2.5
      );
      ctx.globalAlpha = 0.55;
      ctx.stroke();
    }
    ctx.globalAlpha = p.iFrame > 0 && Math.floor(p.iFrame * 18) % 2 === 0 ? 0.45 : 1;

    // body
    const sq = 1 + Math.sin(time * 5) * 0.05;
    ctx.scale(sq, 2 - sq);
    const bg = ctx.createRadialGradient(-p.r * 0.3, -p.r * 0.3, 1, 0, 0, p.r);
    bg.addColorStop(0, '#ffffff');
    bg.addColorStop(0.45, col);
    bg.addColorStop(1, shade(col, -0.35));
    ctx.fillStyle = bg;
    ctx.beginPath(); ctx.arc(0, 0, p.r, 0, TAU); ctx.fill();

    ctx.fillStyle = 'rgba(255,255,255,0.9)';
    ctx.beginPath(); ctx.arc(-p.r * 0.3, -p.r * 0.35, p.r * 0.2, 0, TAU); ctx.fill();
    ctx.restore();
  }

  function shade(hex, amt) {
    const n = parseInt(hex.slice(1), 16);
    let r = (n >> 16) & 255, g = (n >> 8) & 255, b = n & 255;
    r = Math.max(0, Math.min(255, Math.round(r + 255 * amt)));
    g = Math.max(0, Math.min(255, Math.round(g + 255 * amt)));
    b = Math.max(0, Math.min(255, Math.round(b + 255 * amt)));
    return 'rgb(' + r + ',' + g + ',' + b + ')';
  }

  /* ------------------------------------------------------------------ */
  function drawOrbiters() {
    for (const o of Game.orbiters) {
      const id = o.w;
      const w = Game.weapons[id];
      const def = w && w.evolved ? CFG.EVOLUTIONS[id].result : CFG.WEAPONS[id];
      const col = def.color || '#b39cff';
      const size = def.size || 12;
      ctx.save();
      ctx.globalAlpha = 0.3;
      ctx.fillStyle = col;
      ctx.beginPath(); ctx.arc(o.x, o.y, size * 2.1, 0, TAU); ctx.fill();
      ctx.globalAlpha = 1;
      ctx.fillStyle = col;
      ctx.beginPath(); ctx.arc(o.x, o.y, size, 0, TAU); ctx.fill();
      ctx.fillStyle = 'rgba(255,255,255,0.85)';
      ctx.beginPath(); ctx.arc(o.x - size * 0.3, o.y - size * 0.3, size * 0.32, 0, TAU); ctx.fill();
      ctx.restore();
    }
  }

  function drawBullets() {
    ctx.save();
    for (const b of Game.bullets) {
      ctx.globalAlpha = 0.28;
      ctx.fillStyle = b.color;
      ctx.beginPath(); ctx.arc(b.x, b.y, b.r * 2.4, 0, TAU); ctx.fill();
      ctx.globalAlpha = 1;
      const a = Math.atan2(b.vy, b.vx);
      ctx.translate(b.x, b.y);
      ctx.rotate(a);
      ctx.fillStyle = b.color;
      if (b.kind === 'swarm') {
        ctx.beginPath();
        ctx.moveTo(b.r * 1.6, 0); ctx.lineTo(-b.r, b.r); ctx.lineTo(-b.r * 0.4, 0); ctx.lineTo(-b.r, -b.r);
        ctx.closePath(); ctx.fill();
      } else {
        roundRect(-b.r * 1.5, -b.r * 0.5, b.r * 3, b.r, b.r * 0.5); ctx.fill();
        ctx.fillStyle = '#fff';
        roundRect(-b.r * 0.4, -b.r * 0.25, b.r * 1.2, b.r * 0.5, b.r * 0.25); ctx.fill();
      }
      ctx.setTransform(dpr, 0, 0, dpr, -Game.view.camX * dpr, -Game.view.camY * dpr);
    }
    ctx.restore();
  }

  function drawEBullets() {
    ctx.save();
    for (const b of Game.ebullets) {
      ctx.globalAlpha = 0.3;
      ctx.fillStyle = b.color;
      ctx.beginPath(); ctx.arc(b.x, b.y, b.r * 2, 0, TAU); ctx.fill();
      ctx.globalAlpha = 1;
      ctx.fillStyle = b.color;
      ctx.beginPath(); ctx.arc(b.x, b.y, b.r, 0, TAU); ctx.fill();
      ctx.fillStyle = '#fff';
      ctx.beginPath(); ctx.arc(b.x, b.y, b.r * 0.42, 0, TAU); ctx.fill();
    }
    ctx.restore();
  }

  function drawNovae() {
    ctx.save();
    for (const n of Game.novae) {
      const k = n.life / n.max;
      if (n.bolt) {
        ctx.globalAlpha = k;
        ctx.strokeStyle = n.color;
        ctx.lineWidth = 4;
        ctx.shadowColor = n.color;
        ctx.shadowBlur = 14;
        ctx.beginPath();
        ctx.moveTo(n.bolt[0].x, n.bolt[0].y);
        for (let i = 1; i < n.bolt.length; i++) {
          const a = n.bolt[i - 1], b = n.bolt[i];
          const mx = (a.x + b.x) / 2 + (Math.random() - 0.5) * 16;
          const my = (a.y + b.y) / 2 + (Math.random() - 0.5) * 16;
          ctx.lineTo(mx, my);
          ctx.lineTo(b.x, b.y);
        }
        ctx.stroke();
      } else {
        ctx.globalAlpha = k * 0.55;
        ctx.strokeStyle = n.color;
        ctx.lineWidth = 5 * k + 1;
        ctx.shadowColor = n.color;
        ctx.shadowBlur = 18;
        ctx.beginPath(); ctx.arc(n.x, n.y, n.r, 0, TAU); ctx.stroke();
        ctx.globalAlpha = k * 0.13;
        ctx.fillStyle = n.color;
        ctx.beginPath(); ctx.arc(n.x, n.y, n.r, 0, TAU); ctx.fill();
      }
    }
    ctx.restore();
  }

  function drawParticles() {
    ctx.save();
    for (const q of Game.particles) {
      const k = Math.max(0, q.life / q.max);
      ctx.globalAlpha = k;
      ctx.fillStyle = q.color;
      ctx.beginPath(); ctx.arc(q.x, q.y, q.r * k, 0, TAU); ctx.fill();
    }
    ctx.restore();
  }

  function drawFloaters() {
    ctx.save();
    ctx.font = 'bold 15px system-ui, sans-serif';
    ctx.textAlign = 'center';
    for (const f of Game.floaters) {
      ctx.globalAlpha = Math.min(1, f.life / 0.5);
      ctx.lineWidth = 3;
      ctx.strokeStyle = 'rgba(0,0,0,0.6)';
      ctx.strokeText(f.text, f.x, f.y);
      ctx.fillStyle = f.color;
      ctx.fillText(f.text, f.x, f.y);
    }
    ctx.restore();
  }

  /* ------------------------------------------------------------------ *
   * offscreen direction arrows for bosses/elites
   * ------------------------------------------------------------------ */
  function drawOffscreenMarkers() {
    const p = Game.player;
    const margin = 46;
    for (const e of Game.enemies) {
      if (!e.def.isBoss && !e.def.isElite) continue;
      const sx = e.x - Game.view.camX, sy = e.y - Game.view.camY;
      if (sx > -40 && sx < W + 40 && sy > -40 && sy < H + 40) continue;
      const a = Math.atan2(sy - H / 2, sx - W / 2);
      const rx = W / 2 + Math.cos(a) * (W / 2 - margin);
      const ry = H / 2 + Math.sin(a) * (H / 2 - margin);
      ctx.save();
      ctx.translate(rx, ry);
      ctx.rotate(a);
      ctx.globalAlpha = 0.55 + Math.sin(time * 6) * 0.25;
      ctx.fillStyle = e.def.isBoss ? '#ff1f4b' : '#ff3d6e';
      ctx.beginPath();
      ctx.moveTo(14, 0); ctx.lineTo(-8, 9); ctx.lineTo(-8, -9);
      ctx.closePath(); ctx.fill();
      ctx.restore();
    }
  }

  /* ------------------------------------------------------------------ *
   * world-space HUD (boss bar)
   * ------------------------------------------------------------------ */
  function drawBossBar() {
    let boss = null;
    for (const e of Game.enemies) if (e.def.isBoss && !e.dead) { boss = e; break; }
    if (!boss) return;
    const w = Math.min(W - 80, 520), h = 16;
    const x = (W - w) / 2, y = 78;
    ctx.save();
    ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
    ctx.fillStyle = 'rgba(0,0,0,0.6)';
    roundRect(x - 2, y - 2, w + 4, h + 4, 8); ctx.fill();
    const k = Math.max(0, boss.hp / boss.maxHp);
    const g = ctx.createLinearGradient(x, 0, x + w, 0);
    g.addColorStop(0, '#ff1f4b'); g.addColorStop(1, '#ff8fab');
    ctx.fillStyle = g;
    roundRect(x, y, w * k, h, 6); ctx.fill();
    ctx.fillStyle = '#fff';
    ctx.font = 'bold 11px system-ui, sans-serif';
    ctx.textAlign = 'center';
    ctx.fillText('ЛЕВИАФАН', W / 2, y - 6);
    ctx.restore();
  }

  /* ------------------------------------------------------------------ *
   * master render
   * ------------------------------------------------------------------ */
  function render(dt) {
    time += dt;
    if (!ctx) return;

    ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
    drawBackground();

    // world transform with shake
    const sh = Game.shake;
    const ox = sh > 0 ? (Math.random() - 0.5) * sh : 0;
    const oy = sh > 0 ? (Math.random() - 0.5) * sh : 0;
    ctx.setTransform(dpr, 0, 0, dpr, (-Game.view.camX + ox) * dpr, (-Game.view.camY + oy) * dpr);

    drawTraps();
    drawGems();
    drawChests();
    drawEnemies();
    drawOrbiters();
    drawPlayer();
    drawBullets();
    drawEBullets();
    drawNovae();
    drawParticles();
    drawFloaters();

    // screen space
    ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
    drawOffscreenMarkers();
    drawBossBar();

    // damage vignette
    if (Game.flash > 0) {
      ctx.save();
      ctx.globalAlpha = Math.min(0.55, Game.flash * 0.6);
      const g = ctx.createRadialGradient(W / 2, H / 2, Math.min(W, H) * 0.25, W / 2, H / 2, Math.max(W, H) * 0.7);
      g.addColorStop(0, 'rgba(255,0,60,0)');
      g.addColorStop(1, 'rgba(255,0,60,0.9)');
      ctx.fillStyle = g;
      ctx.fillRect(0, 0, W, H);
      ctx.restore();
    }

    // low-hp pulse
    if (Game.state === 'playing' && Game.player && Game.player.hp / Game.player.maxHp < 0.3) {
      ctx.save();
      ctx.globalAlpha = 0.12 + Math.sin(time * 6) * 0.08;
      const g = ctx.createRadialGradient(W / 2, H / 2, Math.min(W, H) * 0.3, W / 2, H / 2, Math.max(W, H) * 0.7);
      g.addColorStop(0, 'rgba(255,0,40,0)');
      g.addColorStop(1, 'rgba(255,0,40,1)');
      ctx.fillStyle = g;
      ctx.fillRect(0, 0, W, H);
      ctx.restore();
    }

    // permanent vignette
    ctx.save();
    const vg = ctx.createRadialGradient(W / 2, H / 2, Math.min(W, H) * 0.42, W / 2, H / 2, Math.max(W, H) * 0.78);
    vg.addColorStop(0, 'rgba(0,0,0,0)');
    vg.addColorStop(1, 'rgba(0,0,0,0.55)');
    ctx.fillStyle = vg;
    ctx.fillRect(0, 0, W, H);
    ctx.restore();
  }

  global.Render = { init, resize, render };
})(typeof window !== 'undefined' ? window : globalThis);

/* ============================================================
   РОЙ — UI. No external fonts/assets: everything inline.
   ============================================================ */
* { box-sizing: border-box; -webkit-tap-highlight-color: transparent; }

html, body {
  margin: 0; padding: 0; width: 100%; height: 100%;
  background: #030d18; overflow: hidden;
  font-family: system-ui, -apple-system, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
  color: #e8f6ff;
  user-select: none; -webkit-user-select: none;
  touch-action: none;
  overscroll-behavior: none;
}

#app { position: fixed; inset: 0; }
#game { position: absolute; inset: 0; width: 100%; height: 100%; display: block; }

.hidden { display: none !important; }

/* ---------------- HUD ---------------- */
#hud { position: absolute; inset: 0; pointer-events: none; z-index: 5; }

.hud-top {
  position: absolute; top: 0; left: 0; right: 0;
  display: flex; align-items: flex-start; gap: 10px;
  padding: 10px 12px;
  padding-top: calc(10px + env(safe-area-inset-top, 0px));
}

.hud-left { flex: 1 1 auto; min-width: 0; max-width: 300px; }
.hud-mid { flex: 0 0 auto; text-align: center; }
.hud-right { flex: 0 0 auto; display: flex; gap: 6px; }

.hpbar, .xpbar {
  position: relative; height: 15px; border-radius: 8px;
  background: rgba(3, 15, 28, 0.72);
  border: 1px solid rgba(120, 200, 255, 0.28);
  overflow: hidden;
}
.xpbar { height: 8px; margin-top: 4px; border-radius: 5px; }

#hpFill {
  height: 100%; width: 100%;
  background: linear-gradient(90deg, #ff4d6d, #ff8fab);
  transition: width .16s ease-out;
  box-shadow: 0 0 12px rgba(255, 77, 109, .6);
}
#xpFill {
  height: 100%; width: 0%;
  background: linear-gradient(90deg, #29d3ff, #a5f3ff);
  transition: width .12s linear;
  box-shadow: 0 0 10px rgba(41, 211, 255, .7);
}

#hpText {
  position: absolute; inset: 0; display: flex; align-items: center; justify-content: center;
  font-size: 10px; font-weight: 800; letter-spacing: .04em;
  text-shadow: 0 1px 2px #000;
}

.hud-sub {
  display: flex; justify-content: space-between;
  margin-top: 3px; font-size: 11px; font-weight: 700;
  color: #8fd4f5; text-shadow: 0 1px 2px #000;
}
#killText::before { content: "☠ "; }

#timer {
  font-size: 26px; font-weight: 900; letter-spacing: .02em;
  text-shadow: 0 2px 10px rgba(0,0,0,.9), 0 0 22px rgba(41,211,255,.35);
  font-variant-numeric: tabular-nums;
}
#scoreText {
  font-size: 12px; font-weight: 800; color: #ffd166;
  text-shadow: 0 1px 3px #000; font-variant-numeric: tabular-nums;
}

.iconbtn {
  pointer-events: auto;
  width: 34px; height: 34px; border-radius: 10px;
  border: 1px solid rgba(120,200,255,.28);
  background: rgba(3,15,28,.72);
  color: #cdeeff; font-size: 15px; line-height: 1;
  cursor: pointer; padding: 0;
}
.iconbtn:active { transform: scale(.92); }
.iconbtn.off { opacity: .4; }

/* loadout chips */
#loadout {
  position: absolute; left: 12px; top: 74px;
  display: flex; flex-wrap: wrap; gap: 5px; max-width: 46%;
}
.chip {
  display: flex; align-items: center; gap: 4px;
  padding: 3px 7px 3px 5px; border-radius: 999px;
  background: rgba(3,15,28,.74);
  border: 1px solid rgba(120,200,255,.26);
  font-size: 11px; font-weight: 800;
  backdrop-filter: blur(4px);
}
.chip i {
  width: 14px; height: 14px; border-radius: 4px; display: block;
  box-shadow: 0 0 8px currentColor;
}
.chip.ev { border-color: #ffe066; box-shadow: 0 0 12px rgba(255,224,102,.35); }

/* banner */
#banner {
  position: absolute; left: 0; right: 0; top: 26%;
  text-align: center; font-size: clamp(20px, 5.5vw, 40px); font-weight: 900;
  letter-spacing: .04em; opacity: 0; transition: opacity .2s;
  text-shadow: 0 3px 16px #000, 0 0 30px currentColor;
  pointer-events: none;
}
#banner.on { opacity: 1; animation: pop .35s ease-out; }
@keyframes pop { 0% { transform: scale(.6); } 60% { transform: scale(1.08); } 100% { transform: scale(1); } }

/* virtual joystick */
#joystick {
  position: absolute; width: 118px; height: 118px; border-radius: 50%;
  border: 2px solid rgba(140,220,255,.22);
  background: radial-gradient(circle, rgba(10,40,70,.30), rgba(10,40,70,.10));
  opacity: 0; transition: opacity .15s; left: 0; top: 0;
  transform: translate(-50%, -50%);
}
#joystick.on { opacity: 1; }
#stick {
  position: absolute; left: 50%; top: 50%; width: 46px; height: 46px;
  margin: -23px 0 0 -23px; border-radius: 50%;
  background: radial-gradient(circle at 35% 30%, #bdf0ff, #29a7d6);
  box-shadow: 0 0 18px rgba(41,211,255,.6);
}

/* ---------------- Screens ---------------- */
#screens { position: absolute; inset: 0; z-index: 10; pointer-events: none; }

.screen {
  position: absolute; inset: 0;
  display: none; align-items: center; justify-content: center;
  padding: 16px;
  padding-top: calc(16px + env(safe-area-inset-top, 0px));
  padding-bottom: calc(16px + env(safe-area-inset-bottom, 0px));
  background: radial-gradient(ellipse at 50% 40%, rgba(6,26,48,.80), rgba(2,9,17,.94));
  backdrop-filter: blur(3px);
  overflow-y: auto;
  pointer-events: auto;
}
.screen.active { display: flex; animation: fade .22s ease-out; }
@keyframes fade { from { opacity: 0 } to { opacity: 1 } }

.panel {
  width: 100%; max-width: 460px;
  background: linear-gradient(170deg, rgba(12,38,66,.96), rgba(5,18,34,.98));
  border: 1px solid rgba(120,200,255,.22);
  border-radius: 20px;
  padding: 22px 20px;
  box-shadow: 0 24px 70px rgba(0,0,0,.65), inset 0 1px 0 rgba(255,255,255,.07);
  text-align: center;
  max-height: calc(100vh - 32px - env(safe-area-inset-top, 0px) - env(safe-area-inset-bottom, 0px));
  overflow-y: auto;
}
.panel.wide { max-width: 620px; }
.panel.small { max-width: 320px; }
.panel.menu { max-width: 420px; }
.panel.level { max-width: 560px; }

.title {
  font-size: clamp(42px, 12vw, 74px); font-weight: 900; line-height: .95;
  letter-spacing: .12em; margin: 0 0 4px;
  background: linear-gradient(180deg, #ffffff, #6fd8ff 60%, #2b9fd0);
  -webkit-background-clip: text; background-clip: text; color: transparent;
  filter: drop-shadow(0 0 26px rgba(41,211,255,.45));
}
.title.sm { font-size: 24px; letter-spacing: .18em; margin-bottom: 14px; }
.tagline { color: #8fd4f5; font-size: 13px; line-height: 1.5; margin-bottom: 18px; }

.boot { text-align: center; }
.boot-title {
  font-size: clamp(50px, 15vw, 92px); font-weight: 900; letter-spacing: .16em;
  background: linear-gradient(180deg, #fff, #6fd8ff);
  -webkit-background-clip: text; background-clip: text; color: transparent;
  filter: drop-shadow(0 0 30px rgba(41,211,255,.5));
}
.boot-sub { color: #6fb9dd; font-size: 12px; letter-spacing: .35em; text-transform: uppercase; margin-bottom: 26px; }
.loader { width: 220px; height: 6px; border-radius: 3px; background: rgba(255,255,255,.1); overflow: hidden; margin: 0 auto 10px; }
#loadBar { height: 100%; width: 0%; background: linear-gradient(90deg,#29d3ff,#a5f3ff); transition: width .3s; }
.hint { color: #5d90ad; font-size: 11px; }

/* buttons */
.btn {
  display: block; width: 100%;
  padding: 13px 16px; margin: 8px 0 0;
  border-radius: 13px; cursor: pointer;
  border: 1px solid rgba(120,200,255,.3);
  background: rgba(20,54,88,.65);
  color: #e8f6ff; font-size: 15px; font-weight: 800; letter-spacing: .02em;
  font-family: inherit;
  transition: transform .08s, background .15s, box-shadow .15s;
}
.btn:hover { background: rgba(30,76,120,.8); }
.btn:active { transform: scale(.97); }
.btn.primary {
  background: linear-gradient(180deg, #2fc0f0, #1379b0);
  border-color: rgba(160,235,255,.5);
  box-shadow: 0 8px 26px rgba(30,160,220,.35);
}
.btn.primary:hover { background: linear-gradient(180deg, #46cdfb, #1788c4); }
.btn.big { padding: 17px; font-size: 19px; letter-spacing: .08em; }
.btn.small { padding: 9px 14px; font-size: 13px; width: auto; }
.btn.gold {
  background: linear-gradient(180deg, #ffd166, #e09b1c);
  border-color: rgba(255,235,180,.6); color: #3a2600;
  box-shadow: 0 8px 26px rgba(255,190,60,.3);
}
.btn.gold small { display: block; font-size: 10.5px; font-weight: 700; opacity: .78; margin-top: 3px; }
.btn:disabled { opacity: .42; cursor: not-allowed; transform: none; }

.btn-row { display: flex; gap: 8px; margin-top: 8px; flex-wrap: wrap; }
.btn-row .btn { flex: 1 1 100px; margin: 8px 0 0; }

.stat-row { display: flex; gap: 8px; margin-bottom: 16px; }
.stat {
  flex: 1; padding: 9px 6px; border-radius: 12px;
  background: rgba(8,28,48,.7); border: 1px solid rgba(120,200,255,.16);
}
.stat b { display: block; font-size: 17px; font-weight: 900; color: #7cf6ff; font-variant-numeric: tabular-nums; }
.stat span { font-size: 10px; color: #6fa8c6; text-transform: uppercase; letter-spacing: .08em; }

.daily {
  margin-top: 14px; padding: 12px; border-radius: 14px;
  background: linear-gradient(180deg, rgba(70,52,10,.8), rgba(38,28,6,.85));
  border: 1px solid rgba(255,209,102,.35);
}
.daily-title { font-weight: 900; color: #ffd166; font-size: 14px; }
.daily-desc { color: #d9c48a; font-size: 11.5px; margin: 4px 0 8px; }
.daily .btn { margin: 0 auto; }

.charbadge { margin-top: 14px; font-size: 12px; color: #8fd4f5; }
.charbadge b { color: #fff; }

/* level up */
.lvl-head { margin-bottom: 14px; }
.lvl-head span {
  display: block; font-size: 26px; font-weight: 900; letter-spacing: .1em; color: #ffe066;
  text-shadow: 0 0 24px rgba(255,224,102,.45);
}
.lvl-head em { font-style: normal; font-size: 12px; color: #8fb8cf; letter-spacing: .1em; text-transform: uppercase; }

.offers { display: flex; gap: 10px; flex-wrap: wrap; justify-content: center; }
.offer {
  flex: 1 1 150px; min-width: 140px; max-width: 190px;
  padding: 16px 12px; border-radius: 16px; cursor: pointer;
  background: linear-gradient(180deg, rgba(18,50,82,.9), rgba(7,24,42,.95));
  border: 2px solid rgba(120,200,255,.25);
  text-align: center; font-family: inherit; color: #e8f6ff;
  transition: transform .1s, box-shadow .15s, border-color .15s;
}
.offer:hover { transform: translateY(-3px); }
.offer:active { transform: scale(.97); }
.offer .oicon {
  width: 46px; height: 46px; margin: 0 auto 9px; border-radius: 13px;
  display: flex; align-items: center; justify-content: center; font-size: 23px;
}
.offer .oname { font-weight: 900; font-size: 14.5px; margin-bottom: 5px; }
.offer .odesc { font-size: 11px; line-height: 1.4; color: #9dc4da; }
.offer.rare { border-color: #ffe066; box-shadow: 0 0 24px rgba(255,224,102,.28); animation: glow 1.5s ease-in-out infinite; }
.offer.evo { border-color: #fff; box-shadow: 0 0 34px rgba(255,255,255,.4); animation: glow 1.1s ease-in-out infinite; }
.offer.evo .oname { color: #fff; }
@keyframes glow { 0%,100% { filter: brightness(1) } 50% { filter: brightness(1.18) } }

/* results */
.result-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 8px; margin-bottom: 14px; }
.result-grid > div {
  padding: 11px 6px; border-radius: 12px;
  background: rgba(8,28,48,.7); border: 1px solid rgba(120,200,255,.16);
}
.result-grid b { display: block; font-size: 21px; font-weight: 900; color: #7cf6ff; font-variant-numeric: tabular-nums; }
.result-grid span { font-size: 10px; color: #6fa8c6; text-transform: uppercase; letter-spacing: .08em; }

.biomass-line {
  display: flex; justify-content: space-between; align-items: center;
  padding: 11px 14px; border-radius: 12px; margin-bottom: 12px;
  background: linear-gradient(90deg, rgba(60,44,8,.75), rgba(38,28,6,.8));
  border: 1px solid rgba(255,209,102,.3);
  font-size: 13px; color: #e6d3a3;
}
.biomass-line b { color: #ffd166; font-size: 18px; font-weight: 900; }
.biomass-line.top { margin-bottom: 14px; }

.tip { margin-top: 12px; font-size: 11.5px; color: #7fb0c9; line-height: 1.5; }

/* lists */
.charlist, .metalist { display: grid; gap: 9px; margin-bottom: 14px; text-align: left; }
.charlist { grid-template-columns: repeat(auto-fill, minmax(160px, 1fr)); }
.metalist { grid-template-columns: repeat(auto-fill, minmax(230px, 1fr)); }

.card {
  padding: 12px; border-radius: 14px;
  background: rgba(8,28,48,.72); border: 1px solid rgba(120,200,255,.18);
  display: flex; gap: 10px; align-items: center;
}
.card.locked { opacity: .5; }
.card.selected { border-color: #7cf6ff; box-shadow: 0 0 0 1px #7cf6ff inset; }
.card .cdot {
  width: 34px; height: 34px; border-radius: 50%; flex: 0 0 34px;
  box-shadow: 0 0 16px currentColor;
}
.card .cbody { flex: 1 1 auto; min-width: 0; }
.card .cname { font-weight: 900; font-size: 14px; }
.card .cdesc { font-size: 10.5px; color: #9dc4da; line-height: 1.35; margin-top: 2px; }
.card .clock { font-size: 10px; color: #ffd166; margin-top: 3px; }
.card .cbuy {
  flex: 0 0 auto; padding: 7px 10px; border-radius: 10px; cursor: pointer;
  border: 1px solid rgba(255,209,102,.4); background: rgba(70,52,10,.8);
  color: #ffd166; font-weight: 900; font-size: 12px; font-family: inherit;
}
.card .cbuy:disabled { opacity: .35; cursor: not-allowed; }
.card .cbuy.max { border-color: rgba(120,200,255,.3); background: rgba(20,54,88,.6); color: #8fd4f5; }
.card .clvl { font-size: 10px; color: #6fa8c6; margin-top: 2px; }

.board { text-align: left; margin-bottom: 14px; max-height: 46vh; overflow-y: auto; }
.brow {
  display: flex; align-items: center; gap: 10px;
  padding: 9px 12px; border-radius: 10px; margin-bottom: 5px;
  background: rgba(8,28,48,.6); font-size: 13px;
}
.brow.me { border: 1px solid rgba(124,246,255,.5); background: rgba(12,48,76,.8); }
.brow .brank { width: 26px; font-weight: 900; color: #7cf6ff; }
.brow .bname { flex: 1; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.brow .bscore { font-weight: 900; color: #ffd166; font-variant-numeric: tabular-nums; }
.board .empty { text-align: center; color: #6fa8c6; padding: 20px; font-size: 13px; }

.help { text-align: left; font-size: 13px; line-height: 1.6; color: #b6d8ea; margin-bottom: 14px; }
.help p { margin: 0 0 10px; }
.help b { color: #fff; }

.offline-note {
  padding: 11px 13px; border-radius: 12px; margin-bottom: 12px;
  background: rgba(10,52,44,.7); border: 1px solid rgba(126,240,190,.3);
  font-size: 12px; color: #b7f0d8;
}

/* narrow phones */
@media (max-width: 430px) {
  .panel { padding: 18px 14px; }
  .offer { flex-basis: 100%; max-width: none; display: flex; align-items: center; gap: 12px; text-align: left; padding: 12px; }
  .offer .oicon { margin: 0; flex: 0 0 46px; }
  #loadout { top: 68px; max-width: 60%; }
  #timer { font-size: 22px; }
}
@media (max-height: 480px) {
  .title { font-size: 38px; }
  .tagline { margin-bottom: 10px; }
  .btn.big { padding: 12px; font-size: 16px; }
  .stat-row { margin-bottom: 10px; }
}

/**
 * ui.js — screens, HUD, input, and the Yandex monetisation touchpoints.
 *
 * Yandex rules honoured here:
 *  - Rewarded button text states BOTH that an ad will play AND the exact reward (rule 1.5).
 *  - Reward is a bonus (revive / 2x biomass), never required to keep playing.
 *  - Gameplay is stopped and audio muted before every fullscreen ad (rule 1.7).
 *  - Interstitials are throttled (>= 60 s, never on the first run).
 */
(function (global) {
  'use strict';

  const Game = global.Game;
  const CFG = global.CFG;
  const $ = (id) => document.getElementById(id);

  const ICONS = {
    spike: '➤', orbit: '◎', nova: '◉', arc: '⚡', swarm: '≋', trap: '◈',
    might: '☠', haste: '➶', vigor: '⬢', focus: '⏱', magnet: '⊕', regen: '✚',
    spike_ev: '➤', orbit_ev: '◎', nova_ev: '◉', arc_ev: '⚡', swarm_ev: '≋', trap_ev: '◈',
    heart: '❤', star: '★',
  };

  const screens = {
    scrBoot: $('scrBoot'), scrMenu: $('scrMenu'), scrLevel: $('scrLevel'),
    scrPause: $('scrPause'), scrOver: $('scrOver'), scrChars: $('scrChars'),
    scrMeta: $('scrMeta'), scrBoard: $('scrBoard'), scrHelp: $('scrHelp'),
  };

  let currentScreen = 'scrBoot';
  let prevState = null;
  let runsSinceAd = 0;
  let reviveOffered = false;
  let offlineInfo = null;
  let dailyClaimedToday = false;

  /* ------------------------------------------------------------------ *
   * screen management
   * ------------------------------------------------------------------ */
  function show(name) {
    Object.keys(screens).forEach((k) => screens[k].classList.toggle('active', k === name));
    currentScreen = name;
    $('hud').classList.toggle('hidden', name !== '__none__');
  }
  function hideAll() {
    Object.keys(screens).forEach((k) => screens[k].classList.remove('active'));
    currentScreen = null;
    $('hud').classList.remove('hidden');
  }
  UI_show = show;

  /* ------------------------------------------------------------------ *
   * HUD
   * ------------------------------------------------------------------ */
  function fmtTime(s) {
    s = Math.max(0, Math.floor(s));
    const m = Math.floor(s / 60);
    const r = s % 60;
    return m + ':' + (r < 10 ? '0' : '') + r;
  }

  function updateHud() {
    const p = Game.player;
    if (!p) return;
    const hpk = Math.max(0, p.hp / p.maxHp);
    $('hpFill').style.width = (hpk * 100).toFixed(1) + '%';
    $('hpText').textContent = Math.ceil(p.hp) + ' / ' + Math.round(p.maxHp);
    $('xpFill').style.width = Math.min(100, (Game.xp / Game.xpNeed) * 100).toFixed(1) + '%';
    $('lvlText').textContent = 'Ур. ' + Game.level;
    $('killText').textContent = Game.kills;
    $('timer').textContent = fmtTime(Game.t);
    $('scoreText').textContent = Game.score.toLocaleString('ru-RU');
  }

  function renderLoadout() {
    const box = $('loadout');
    if (!box) return;
    let html = '';
    for (const id of Object.keys(Game.weapons)) {
      const w = Game.weapons[id];
      const def = CFG.WEAPONS[id];
      const ev = w.evolved ? CFG.EVOLUTIONS[id].result : null;
      const color = ev ? ev.color : def.color;
      html += '<div class="chip' + (ev ? ' ev' : '') + '" style="color:' + color + '">' +
        '<i style="background:' + color + '"></i>' +
        '<span style="color:#e8f6ff">' + (ev ? ev.name : def.name) + '</span>' +
        '<span style="color:' + color + '">' + (ev ? 'MAX' : w.level) + '</span></div>';
    }
    for (const id of Object.keys(Game.passives)) {
      const def = CFG.PASSIVES[id];
      html += '<div class="chip" style="color:' + def.color + '">' +
        '<i style="background:' + def.color + '"></i>' +
        '<span style="color:#e8f6ff">' + def.name + '</span>' +
        '<span style="color:' + def.color + '">' + Game.passives[id] + '</span></div>';
    }
    box.innerHTML = html;
  }

  /* ------------------------------------------------------------------ *
   * banner
   * ------------------------------------------------------------------ */
  let bannerTimer = null;
  function banner(text, color) {
    const el = $('banner');
    el.textContent = text;
    el.style.color = color || '#fff';
    el.classList.add('on');
    if (bannerTimer) clearTimeout(bannerTimer);
    bannerTimer = setTimeout(() => el.classList.remove('on'), 2200);
  }

  /* ------------------------------------------------------------------ *
   * menu
   * ------------------------------------------------------------------ */
  function renderMenu() {
    const m = Game.meta;
    $('mBest').textContent = m.bestScore.toLocaleString('ru-RU');
    $('mTime').textContent = fmtTime(m.bestTime);
    $('mBiomass').textContent = m.biomass.toLocaleString('ru-RU');

    const ch = CFG.CHARACTERS.find((c) => c.id === Game.charId) || CFG.CHARACTERS[0];
    $('charBadge').innerHTML = 'Герой: <b style="color:' + ch.color + '">' + ch.name + '</b> · ' + ch.desc;

    // daily bonus
    const today = new Date().toISOString().slice(0, 10);
    dailyClaimedToday = m.daily && m.daily.day === today && m.daily.bonusUsed;
    $('dailyBox').classList.toggle('hidden', dailyClaimedToday);

    if (offlineInfo) {
      $('offlineNote').classList.remove('hidden');
      $('offlineNote').innerHTML = '🌙 Пока вас не было (' + fmtClock(offlineInfo.minutes) + '), ' +
        'организм рос: <b style="color:#ffd166">+' + offlineInfo.amount + '</b> биомассы';
    }
  }

  function fmtClock(min) {
    if (min < 60) return min + ' мин';
    const h = Math.floor(min / 60);
    const r = min % 60;
    return h + ' ч' + (r ? ' ' + r + ' мин' : '');
  }

  /* ------------------------------------------------------------------ *
   * characters screen
   * ------------------------------------------------------------------ */
  function renderChars() {
    const box = $('charList');
    box.innerHTML = '';
    CFG.CHARACTERS.forEach((c) => {
      const unlocked = Game.isCharUnlocked(c.id);
      const div = document.createElement('div');
      div.className = 'card' + (unlocked ? '' : ' locked') + (Game.charId === c.id ? ' selected' : '');
      div.innerHTML =
        '<div class="cdot" style="background:' + c.color + ';color:' + c.color + '"></div>' +
        '<div class="cbody"><div class="cname">' + c.name + (unlocked ? '' : ' 🔒') + '</div>' +
        '<div class="cdesc">' + c.desc + '</div>' +
        (unlocked ? '' : '<div class="clock">' + c.unlock.text + '</div>') + '</div>';
      if (unlocked) {
        div.style.cursor = 'pointer';
        div.addEventListener('click', () => {
          Game.charId = c.id;
          global.Audio2.SFX.click();
          renderChars();
          renderMenu();
        });
      }
      box.appendChild(div);
    });
  }

  /* ------------------------------------------------------------------ *
   * meta upgrades screen
   * ------------------------------------------------------------------ */
  function renderMeta() {
    $('metaBiomass').textContent = Game.meta.biomass.toLocaleString('ru-RU');
    const box = $('metaList');
    box.innerHTML = '';
    CFG.META.forEach((item) => {
      const lvl = Game.meta.upgrades[item.id] || 0;
      const maxed = lvl >= item.max;
      const cost = CFG.metaCost(item, lvl);
      const can = !maxed && Game.meta.biomass >= cost;
      const div = document.createElement('div');
      div.className = 'card';
      div.innerHTML =
        '<div class="cdot" style="background:' + item.color + ';color:' + item.color + '"></div>' +
        '<div class="cbody"><div class="cname">' + item.name + '</div>' +
        '<div class="cdesc">' + item.desc + '</div>' +
        '<div class="clvl">Уровень ' + lvl + ' / ' + item.max + '</div></div>';
      const btn = document.createElement('button');
      btn.className = 'cbuy' + (maxed ? ' max' : '');
      btn.textContent = maxed ? 'МАКС' : cost + ' ⬢';
      btn.disabled = !can;
      btn.addEventListener('click', (ev) => {
        ev.stopPropagation();
        if (Game.buyUpgrade(item.id)) renderMeta();
        else global.Audio2.SFX.deny();
      });
      div.appendChild(btn);
      box.appendChild(div);
    });
  }

  /* ------------------------------------------------------------------ *
   * leaderboard
   * ------------------------------------------------------------------ */
  async function renderBoard() {
    const box = $('boardList');
    box.innerHTML = '<div class="empty">загрузка…</div>';
    let rows = [];
    try { rows = await global.SDK.getTopScores('roy_best', 12); } catch (e) { rows = []; }
    if (!rows.length) {
      box.innerHTML = '<div class="empty">Рейтинг доступен в Яндекс Играх.<br>' +
        'Ваш рекорд: <b style="color:#ffd166">' + Game.meta.bestScore.toLocaleString('ru-RU') + '</b></div>';
      return;
    }
    box.innerHTML = rows.map((r) =>
      '<div class="brow' + (r.isMe ? ' me' : '') + '">' +
      '<span class="brank">' + r.rank + '</span>' +
      '<span class="bname">' + escapeHtml(r.name) + (r.isMe ? ' (вы)' : '') + '</span>' +
      '<span class="bscore">' + r.score.toLocaleString('ru-RU') + '</span></div>'
    ).join('');
  }

  function escapeHtml(s) {
    return String(s).replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
  }

  /* ------------------------------------------------------------------ *
   * level-up offers
   * ------------------------------------------------------------------ */
  function renderOffers(offers) {
    $('lvlHead').textContent = 'УРОВЕНЬ ' + Game.level;
    const box = $('offers');
    box.innerHTML = '';
    offers.forEach((o, i) => {
      const b = document.createElement('button');
      b.className = 'offer' + (o.kind === 'evolution' ? ' evo' : o.rare ? ' rare' : '');
      b.innerHTML =
        '<div class="oicon" style="background:' + hexA(o.color, 0.18) + ';color:' + o.color + '">' +
        (ICONS[o.icon] || '●') + '</div>' +
        '<div><div class="oname" style="color:' + o.color + '">' + o.name + '</div>' +
        '<div class="odesc">' + o.desc + '</div></div>';
      b.addEventListener('click', () => {
        Game.chooseOffer(i);
      });
      box.appendChild(b);
    });
    show('scrLevel');
  }

  function hexA(hex, a) {
    const n = parseInt(hex.slice(1), 16);
