import { chromium } from 'playwright-core';
import { spawn } from 'node:child_process';

const PORT = 8126;
const server = spawn('python3', ['-m', 'http.server', String(PORT), '--bind', '0.0.0.0'], { cwd: '/home/user/yandex-game', stdio: 'ignore' });
await new Promise(r => setTimeout(r, 1200));

const browser = await chromium.launch({
  executablePath: '/home/user/.cache/ms-playwright/chromium-1148/chrome-linux/chrome',
  args: ['--no-sandbox'],
});

for (const vp of [{ w: 1440, h: 900, label: 'desktop 1440x900 dpr2' }, { w: 412, h: 823, label: 'mobile 412x823 dpr2' }]) {
  const page = await browser.newPage({ viewport: { width: vp.w, height: vp.h }, deviceScaleFactor: 2 });
  page.on('pageerror', e => console.log('  PAGEERROR', e.message));
  await page.goto(`http://127.0.0.1:${PORT}/index.html`, { waitUntil: 'load' });
  await page.waitForFunction(() => window.Game && window.Game.meta, null, { timeout: 15000 });
  await page.click('#btnPlay');
  await page.waitForFunction(() => Game.state === 'playing', null, { timeout: 5000 });

  const r = await page.evaluate(async () => {
    // heavy scene
    Game.t = 560;
    ['spike', 'orbit', 'nova', 'arc', 'swarm', 'trap'].forEach(w => { Game.weapons[w] = { level: 8, timer: 0.05, evolved: false }; });
    Game.orbiters.length = 0;
    for (let i = 0; i < 200; i++) {
      const a = Math.random() * Math.PI * 2, d = 120 + Math.random() * 500;
      Game.enemies.push({
        type: 'drifter', def: CFG.ENEMY_TYPES.drifter,
        x: Game.player.x + Math.cos(a) * d, y: Game.player.y + Math.sin(a) * d,
        vx: 0, vy: 0, hp: 9999, maxHp: 9999, dmg: 0, r: 13, speed: 62, xp: 3, color: '#ff6b81',
        knockX: 0, knockY: 0, slowT: 0, slowAmt: 0, hitFlash: 0, cd: 1, wobbleA: 0, spawnT: 0, summonT: 99,
      });
    }
    Game.input.kx = 1; Game.input.ky = 0.3;

    const canvas = document.getElementById('game');
    const info = { cssW: canvas.clientWidth, cssH: canvas.clientHeight, bufW: canvas.width, bufH: canvas.height, dpr: Game.view.dpr, pixels: canvas.width * canvas.height };

    // measure simulation alone
    const origRender = Render.render;
    Render.render = () => {};
    await new Promise(r => setTimeout(r, 2500));
    let f = Game.frame; let t0 = performance.now();
    await new Promise(r => setTimeout(r, 3000));
    const simMs = ((performance.now() - t0) / (Game.frame - f));

    // measure render alone (sim frozen)
    Game.state = 'paused';
    Render.render = origRender;
    let frames = 0;
    const probe = (dt) => { frames++; };
    const or2 = Render.render;
    Render.render = function (dt) { frames++; return or2(dt); };
    t0 = performance.now();
    await new Promise(r => setTimeout(r, 3000));
    const renderFps = frames / ((performance.now() - t0) / 1000);
    Render.render = or2;

    return {
      ...info,
      enemies: Game.enemies.length,
      simMsPerTick: Math.round(simMs * 100) / 100,
      renderFps: Math.round(renderFps),
      renderMsPerFrame: Math.round((1000 / renderFps) * 100) / 100,
    };
  });

  console.log(`\n=== ${vp.label} ===`);
  console.log(`  canvas buffer: ${r.bufW}x${r.bufH} = ${(r.pixels / 1e6).toFixed(2)} MP   (css ${r.cssW}x${r.cssH}, dpr ${r.dpr.toFixed(2)})`);
  console.log(`  simulation : ${r.simMsPerTick} ms/tick  (budget 16.7)`);
  console.log(`  render     : ${r.renderFps} fps = ${r.renderMsPerFrame} ms/frame  (enemies=${r.enemies})`);
  console.log(`  combined   : ${(r.simMsPerTick + r.renderMsPerFrame).toFixed(2)} ms/frame -> ~${Math.round(1000 / (r.simMsPerTick + r.renderMsPerFrame))} fps`);
  await page.close();
}

await browser.close();
server.kill();

